def min_cost_to_paint(n, m, rectangles):
    # Initialize the grid with all cells as white (0)
    grid = [[0] * (n + 1) for _ in range(n + 1)]

    # Mark black cells
    for x1, y1, x2, y2 in rectangles:
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                grid[i][j] = 1

    # Calculate the minimum cost
    total_cost = 0
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            if grid[x][y] == 1:
                # Find the rightmost and topmost black cell in the current row and column
                right = x
                while right <= n and grid[right][y] == 1:
                    right += 1
                top = y
                while top <= n and grid[x][top] == 1:
                    top += 1

                # Calculate the cost of painting this rectangle white
                h = right - x
                w = top - y
                total_cost += min(h, w)

                # Mark the painted cells as white
                for i in range(x, right):
                    for j in range(y, top):
                        grid[i][j] = 0

    return total_cost

