import sys

def solve(n, rectangles):
    events = []
    for x1, y1, x2, y2 in rectangles:
        events.append((x1, 0, y1, y2))
        events.append((x2 + 1, 1, y1, y2))
    events.sort()

    active = []
    total_cost = 0
    prev_x = 0

    for x, event_type, y1, y2 in events:
        if x > prev_x:
            width = x - prev_x
            height = n
            for start, end in active:
                height -= max(0, min(end, n) - max(start, 1))
            if height > 0:
                total_cost += min(height, width)

        if event_type == 0:
            active.append((y1, y2))
            active.sort()
        else:
            active.remove((y1, y2))

        prev_x = x

    return total_cost

def main():
    n, m = map(int, input().split())
    rectangles = [tuple(map(int, input().split())) for _ in range(m)]
    print(solve(n, rectangles))

if __name__ == "__main__":
    main()
